Given this TypeScript function, refactor it by extracting the validation logic and the formatting logic into separate pure functions. Keep the same public API. Do not change behavior:
```ts
function processOrder(order: { items: { price: number; qty: number }[]; tax: number; discount: number }): string {
  if (!order.items || !Array.isArray(order.items)) throw new Error('Invalid items');
  if (order.items.length === 0) throw new Error('No items');
  if (typeof order.tax !== 'number' || order.tax < 0) throw new Error('Invalid tax');
  let subtotal = 0;
  for (const item of order.items) {
    if (typeof item.price !== 'number' || item.price < 0) throw new Error('Invalid price');
    if (typeof item.qty !== 'number' || item.qty < 0) throw new Error('Invalid qty');
    subtotal += item.price * item.qty;
  }
  const total = subtotal + subtotal * order.tax - order.discount;
  return '$' + total.toFixed(2);
}
```

